class Solution {
public:
    int minDominoRotations(vector<int>& tops, vector<int>& bottoms) {
        int n = tops.size();
        auto check = [&](int x) -> int {
            int rot_top = 0, rot_bot = 0;
            for (int i = 0; i < n; ++i) {
                if (tops[i] != x && bottoms[i] != x) return -1;
                if (tops[i] != x) rot_top++;
                else if (bottoms[i] != x) rot_bot++;
            }
            return min(rot_top, rot_bot);
        };
        int res = check(tops[0]);
        if (res != -1 || tops[0] == bottoms[0]) return res;
        return check(bottoms[0]);
    }
};

class Solution {
    public int minDominoRotations(int[] tops, int[] bottoms) {
        int res = check(tops, bottoms, tops[0]);
        if (res != -1 || tops[0] == bottoms[0]) return res;
        return check(tops, bottoms, bottoms[0]);
    }

    private int check(int[] tops, int[] bottoms, int x) {
        int rotTop = 0, rotBot = 0;
        for (int i = 0; i < tops.length; ++i) {
            if (tops[i] != x && bottoms[i] != x) return -1;
            if (tops[i] != x) rotTop++;
            else if (bottoms[i] != x) rotBot++;
        }
        return Math.min(rotTop, rotBot);
    }
}

var minDominoRotations = function(tops, bottoms) {
    const check = function(x) {
        let rotTop = 0, rotBot = 0;
        for (let i = 0; i < tops.length; i++) {
            if (tops[i] !== x && bottoms[i] !== x) return -1;
            if (tops[i] !== x) rotTop++;
            else if (bottoms[i] !== x) rotBot++;
        }
        return Math.min(rotTop, rotBot);
    };
    const res = check(tops[0]);
    if (res !== -1 || tops[0] === bottoms[0]) return res;
    return check(bottoms[0]);
};
